from pathlib import Path
import re

p = Path('sim03/public/index.html')
s = p.read_text()

css_anchor = ".result-section{margin-top:26px}.result-section>.eyebrow{margin-bottom:10px}.result-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.result-grid .outcome{margin-top:0}.result-grid .card{min-height:0}@media(max-width:760px){.result-grid{grid-template-columns:1fr}}\n"
css_repl = css_anchor + ".result-hero{border:1px solid #8A6427;background:rgba(240,166,60,.07);padding:22px 24px;margin:20px 0 28px}.result-hero h3{font:10px var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--amber);margin-bottom:8px}.result-hero p{font-size:21px;line-height:1.55;color:var(--bone)}.timeline{display:grid;gap:12px}.timeline-year{display:grid;grid-template-columns:90px 1fr;gap:14px;align-items:start}.timeline-label{font:600 12px var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--amber);padding-top:18px}.timeline-body{display:grid;gap:10px}.timeline-body .outcome{margin-top:0}@media(max-width:760px){.timeline-year{grid-template-columns:1fr}.timeline-label{padding-top:0}}\n"
if css_anchor not in s:
    raise SystemExit('result CSS anchor missing')
s = s.replace(css_anchor, css_repl, 1)

fn_anchor = "function miniAlloc(a){return `<div class=\"mini\">${C.lines.map(l=>`<div><b>${a[l.id]}</b><span>${esc(l.label)}</span></div>`).join('')}</div>`}\nasync function finish(){"
fn_repl = """function miniAlloc(a){return `<div class=\"mini\">${C.lines.map(l=>`<div><b>${a[l.id]}</b><span>${esc(l.label)}</span></div>`).join('')}</div>`}\nfunction overallOutcomeText(){\n  const y1=(S.allOutcomes?.year1||S.year1Outcome)?.band;\n  const heat=(S.allOutcomes?.year2||S.year2Outcome)?.heat?.band;\n  const competitor=(S.allOutcomes?.year2||S.year2Outcome)?.competitor?.band;\n  const y3=S.allOutcomes?.year3?.band;\n  const a={\n    strong:'Customer reporting became a real capability early.',\n    middle:'Customer reporting became possible, but slowly and with manual work.',\n    weak:'The first customer request exposed a reporting gap.'\n  }[y1]||'';\n  const b={\n    strong:'Operational resilience held when the heat wave tested the company.',\n    middle:'The heat wave strained operations but did not fully break them.',\n    weak:'The heat wave exposed a serious resilience weakness.'\n  }[heat]||'';\n  const c={\n    strong:'Midland could answer the competitor from a position of strength.',\n    middle:'Midland could only mount a limited pilot response to the competitor.',\n    weak:'Midland could not respond quickly to the competitor’s new service model.'\n  }[competitor]||'';\n  const d={\n    strong:'By Year 3, the architecture supported predictive service as something Midland could actually sell.',\n    pilot:'By Year 3, predictive service was promising, but still only a pilot.',\n    weak:'By Year 3, the architecture still lacked the usable data foundation for predictive service.'\n  }[y3]||'';\n  return [a,b,c,d].filter(Boolean).join(' ');\n}\nasync function finish(){"""
if fn_anchor not in s:
    raise SystemExit('miniAlloc/finish anchor missing')
s = s.replace(fn_anchor, fn_repl, 1)

pat = re.compile(r"  if\(S\.finished\)\{\n    const y1o=.*?\n    return;\n  \}\n  shell\(`", re.S)
m = pat.search(s)
if not m:
    raise SystemExit('finished block not found')
new_block = """  if(S.finished){\n    const y1o=S.allOutcomes?.year1||S.year1Outcome||null;\n    const y2o=S.allOutcomes?.year2||S.year2Outcome||null;\n    const y3o=S.allOutcomes?.year3||null;\n    const cum=y3o?.cumulative||(S.year1&&S.year2?runningTotals(S.year1,S.year2):null);\n    const overall=overallOutcomeText();\n    shell(`<div class=\"eyebrow\">Your outcome</div><h2>What your architecture made possible.</h2>\n    <p class=\"lede\">This is not a score or grade. It is the chain of consequences produced by the portfolio you committed.</p>\n    ${overall?`<div class=\"result-hero\"><h3>Overall result</h3><p>${esc(overall)}</p></div>`:''}\n    <div class=\"result-section\"><div class=\"eyebrow\">Three-year consequence timeline</div>\n      <div class=\"timeline\">\n        <div class=\"timeline-year\"><div class=\"timeline-label\">Year 1</div><div class=\"timeline-body\">${y1o?`<div class=\"outcome\"><h3>${esc(y1o.title)}</h3><p>${esc(y1o.narrative)}</p></div>`:'<div class=\"card\"><p>Outcome unavailable.</p></div>'}</div></div>\n        <div class=\"timeline-year\"><div class=\"timeline-label\">Year 2</div><div class=\"timeline-body\">\n          ${y2o?.heat?`<div class=\"outcome\"><h3>${esc(y2o.heat.title)}</h3><p>${esc(y2o.heat.narrative)}</p></div>`:''}\n          ${y2o?.competitor?`<div class=\"outcome\"><h3>${esc(y2o.competitor.title)}</h3><p>${esc(y2o.competitor.narrative)}</p></div>`:''}\n        </div></div>\n        <div class=\"timeline-year\"><div class=\"timeline-label\">Year 3</div><div class=\"timeline-body\">${y3o?`<div class=\"outcome\"><h3>${esc(y3o.title)}</h3><p>${esc(y3o.narrative)}</p></div>`:'<div class=\"card\"><p>Outcome unavailable.</p></div>'}</div></div>\n      </div>\n    </div>\n    <div class=\"result-section\"><div class=\"eyebrow\">The portfolio that produced this</div>\n      <div class=\"result-grid\">\n        <div class=\"card\"><h3>Year 1 allocation</h3>${S.year1?miniAlloc(S.year1):'<p>—</p>'}</div>\n        <div class=\"card\"><h3>Year 2 allocation</h3>${S.year2?miniAlloc(S.year2):'<p>—</p>'}</div>\n        <div class=\"card\" style=\"grid-column:1/-1\"><h3>Cumulative portfolio</h3>${cum?miniAlloc(cum):'<p>—</p>'}</div>\n      </div>\n    </div>\n    <div class=\"result-section\"><div class=\"eyebrow\">Your original view</div>\n      <div class=\"card\"><p>${esc(S.strategicView||'—')}</p></div>\n    </div>\n    <div class=\"result-section\"><div class=\"eyebrow\">Your reflections</div>\n      <div class=\"card\"><h3>${esc(C.reflectionPrompts[0])}</h3><p style=\"white-space:pre-wrap\">${esc(S.reflection1||'—')}</p></div>\n      <div class=\"card\" style=\"margin-top:12px\"><h3>${esc(C.reflectionPrompts[1])}</h3><p style=\"white-space:pre-wrap\">${esc(S.reflection2||'—')}</p></div>\n    </div>\n    ${notice('Run complete. The full outcome, portfolio and reflections are ready to screenshot or print to PDF.')}\n    <div class=\"actions\"><button class=\"btn pri\" id=\"printBtn\">Print / save PDF</button></div>`);\n    document.getElementById('printBtn').onclick=()=>window.print();\n    return;\n  }\n  shell(`"""
s = s[:m.start()] + new_block + s[m.end():]
p.write_text(s)

p = Path('sim03/build.js')
b = p.read_text()
anchor = "for (const marker of ['Briefing & exhibits','Full results','Year 2 allocation','Cumulative portfolio','What happened'])\n  if (!index.includes(marker)) refuse('briefing/full-results marker missing: ' + marker);"
repl = "for (const marker of ['Briefing & exhibits','Your outcome','Overall result','Three-year consequence timeline','The portfolio that produced this','Your original view','Year 2 allocation','Cumulative portfolio'])\n  if (!index.includes(marker)) refuse('briefing/outcome-results marker missing: ' + marker);\nif (!index.includes('function overallOutcomeText()')) refuse('deterministic overall outcome synthesis missing');\nfor (const forbidden of ['Score:','Grade:','Rank:']) if (index.includes(forbidden)) refuse('grade-like final result leaked: ' + forbidden);"
if anchor not in b:
    raise SystemExit('build result marker anchor missing')
b = b.replace(anchor, repl, 1)
p.write_text(b)
